    "Paj lug lus Askiv": [
      ["It's a piece of cake.","/ɪts‿ə piːs‿əv keɪk/","Yooj yim heev.","Yam yooj yim: The test was a piece of cake."],
      ["I'm on cloud nine.","/aɪm‿ɑːn klaʊd naɪn/","Kuv zoo siab kawg.","Thaum koj zoo siab heev."],
      ["It costs an arm and a leg.","/ɪt kɑːsts‿ən‿ɑːrm‿ən‿ə leg/","Kim heev.","Kim npaum li koj yuav tsum them nqi nrog koj txhais tes thiab txhais ceg."],
      ["Let's call it a day.","/lets kɑːl‿ɪt‿ə deɪ/","Hnub no ua txog ntawm no xwb.","Thaum ua hauj lwm los yog kawm tas."],
      ["I'm feeling under the weather.","/aɪm ˈfiːlɪŋ‿ˈʌndɚ ðə ˈweðɚ/","Kuv tsis nyob zoo mentsis.","Mob me me, zoo li khaub thuas. Tsis yog huab cua."],
      ["I need to hit the books.","/aɪ niːd tə hɪt ðə bʊks/","Kuv yuav tsum kawm ntawv heev.","Ua ntej xeem. Tsis yog ntaus phau ntawv!"],
      ["Once in a blue moon","/wʌns‿ɪn‿ə bluː muːn/","Ntev ntev ib zaug","Yam tsawg heev: I only eat fast food once in a blue moon."],
      ["Better late than never.","/ˈbetɚ leɪt ðən ˈnevɚ/","Lig los zoo dua tsis ua.","Hais rau neeg pib lig."],
      ["Don't beat around the bush.","/doʊnt biːt‿əˈraʊnd ðə bʊʃ/","Hais ncaj ncaj.","Thaum koj xav kom neeg hais yam tseeb."],
      ["It's not my cup of tea.","/ɪts nɑːt maɪ kʌp‿əv tiː/","Kuv tsis nyiam yam no.","Txoj kev zoo hais tias koj tsis nyiam."],
      ["Let's get the ball rolling.","/lets get ðə bɑːl ˈroʊlɪŋ/","Wb pib.","Thaum pib sib ntsib los yog pib hauj lwm."],
      ["I'll keep my fingers crossed.","/aɪl kiːp maɪ ˈfɪŋgɚz krɑːst/","Kuv thov kom koj hmoov zoo.","Hais thaum koj xav kom lwm tus muaj hmoov zoo."],
      ["Hang in there.","/hæŋ‿ɪn ðer/","Ua siab ntev.","Hais rau neeg uas tab tom muaj yam nyuaj."],
      ["Speak of the devil!","/spiːk‿əv ðə ˈdevəl/","Nyuam qhuav hais nws, nws tuaj lawm!","Thaum tus neeg nej tab tom tham txog tuaj txog."],
      ["The ball is in your court.","/ðə bɑːl‿ɪz‿ɪn jʊr kɔːrt/","Tam sim no koj yuav tsum txiav.","Los ntawm kev ua si ntaus pob."],
      ["My lips are sealed.","/maɪ lɪps‿ɑːr siːld/","Kuv yuav tsis qhia leej twg.","Zoo li di ncauj kaw lawm."],
      ["It's on the tip of my tongue.","/ɪts‿ɑːn ðə tɪp‿əv maɪ tʌŋ/","Kuv paub, tab sis kuv nco tsis tau.","Thaum koj paub ib lo lus tab sis nco tsis tau."],
      ["I'm all ears.","/aɪm‿ɑːl‿ɪrz/","Kuv mloog koj.","Kuv mloog zoo heev; hais tuaj."],
      ["When pigs fly.","/wen pɪgz flaɪ/","Yeej tsis muaj hnub ntawd.","Yam yuav tsis muaj: He'll clean his room when pigs fly."]
    ],
    "Movies, TV thiab slang": [
      ["Spill the tea.","/spɪl ðə tiː/","Qhia zaj dab neeg rau kuv.","tea = lus neeg tham txog lwm tus. Slang rau phooj ywg."],
      ["No cap.","/noʊ kæp/","Tseeb, tsis dag.","Slang ntawm cov hluas. cap = dag."],
      ["That song slaps.","/ðæt sɑːŋ slæps/","Zaj hu nkauj ntawd zoo kawg.","slaps = zoo kawg (nkauj). Kuj siv rau mov."],
      ["I'm dead.","/aɪm ded/","Kuv luag tuag lawm.","Tsis yog tuag. Neeg sau nrog daim duab pob txha taub hau."],
      ["Low-key","/ˈloʊkiː/","Mentsis; tsis qhia leej twg","I low-key love this song. Lo lus sib txawv: high-key."],
      ["I'm obsessed with this song.","/aɪm‿əbˈsest wɪð ðɪs sɑːŋ/","Kuv nyiam zaj hu nkauj no kawg.","obsessed = nyiam heev. Siv rau yam zoo."],
      ["What's it about?","/wʌts‿ɪt‿əˈbaʊt/","Nws yog zaj dab neeg dab tsi?","Nug txog movie los yog TV."],
      ["No spoilers!","/noʊ ˈspɔɪlɚz/","Tsis txhob qhia qhov kawg!","Lwm yam: No spoilers, please!"],
      ["I binge-watched the whole season.","/aɪ ˈbɪndʒwɑːtʃt ðə hoʊl ˈsiːzən/","Kuv saib txhua zaj tas hauv ib zaug.","binge-watch = saib ntau zaj hauv ib zaug. season = cov zaj ntawm ib xyoo."],
      ["The ending was so good.","/ði ˈendɪŋ wəz soʊ gʊd/","Qhov kawg zoo heev.","Tsis zoo: The ending was bad."],
      ["It's a must-watch.","/ɪts‿ə ˈmʌstwɑːtʃ/","Koj yuav tsum saib.","Thaum koj xav kom phooj ywg saib heev."],
      ["Plot twist!","/plɑːt twɪst/","Txawv, tsis tau xav txog!","Kuj siv thaum muaj yam koj tsis tau xav txog tshwm sim."],
      ["It's overrated.","/ɪts‿ˌoʊvɚˈreɪtɪd/","Neeg hais tias zoo dhau qhov tseeb.","Neeg qhia tias nws zoo, tab sis koj tsis pom zoo."],
      ["That scene gave me chills.","/ðæt siːn geɪv mi tʃɪlz/","Qhov ntawd ua rau kuv tshee.","Thaum koj ntshai los yog zoo siab heev."],
      ["Who's your favorite player?","/huːz jʊr ˈfeɪvərɪt ˈpleɪɚ/","Koj nyiam tus neeg ua si twg tshaj?","Nug txog kev ua si. Kuj nug: Who's your favorite singer?"],
      ["Are you kidding me?","/ɑːr ju ˈkɪdɪŋ mi/","Koj dag kuv los?","Neeg hais ntau hauv movies: xav tsis txog los yog chim."],
      ["I've got your back.","/aɪv gɑːt jʊr bæk/","Kuv pab koj.","Kuv nrog koj, kuv yuav tiv thaiv koj."],
      ["Gotcha.","/ˈgɑːtʃə/","Nkag siab lawm.","Luv ntawm got you. Siv ntau tshaj rau nkag siab."],
      ["Let's do this!","/lets duː ðɪs/","Wb ua!","Hais ua ntej pib, kom muaj zog."]
    ],
